package cn.autolabel.engine;

import com.google.gson.*;
import java.sql.Connection;
import java.util.*;
import static cn.autolabel.engine.TrackTimelines.*;

/** 轨迹版本只记录显式编辑；生成贡献和素材版本由独立生成事务管理。 */
final class Tracks {
    final Engine engine;final Store store;final TrackTimelines timelines;
    TrackGenerations generations;
    Tracks(Engine engine){this.engine=engine;store=engine.store;timelines=new TrackTimelines(engine);}
    static JsonObject helper(JsonObject track){return Json.obj("trackId",track.get("id"),"objectId",track.get("objectId"),"sourceVideoId",track.get("sourceVideoId"),"templateHash",track.get("templateHash"),"keyframes",Json.array(track,"keyframes").deepCopy());}
    static JsonObject view(Connection c,JsonObject track)throws Exception{
        JsonObject result=new JsonObject();for(String field:List.of("id","timelineId","sourceVideoId","objectId","classId","name","version","status","templateHash","createdAt","updatedAt","sequence"))result.add(field,track.get(field));result.addProperty("keyframeCount",Json.array(track,"keyframes").size());long pending=Json.number(Store.one(c,"SELECT COUNT(*) AS n FROM track_dirty_frames WHERE track_id=?",Json.required(track,"id")),"n",0);result.addProperty("needsRecompute",pending>0);result.addProperty("pendingFrameCount",pending);return result;
    }
    static JsonObject record(JsonObject timeline,String classId,String title,String objectId){return Json.obj("id",Json.id(),"timelineId",timeline.get("id"),"sourceVideoId",timeline.get("sourceVideoId"),"objectId",objectId==null?"object-"+Json.id():objectId,"classId",classId,"name",title,"version",1,"status","active","templateHash",timeline.get("templateHash"),"keyframes",new JsonArray(),"createdAt",Json.now(),"updatedAt",Json.now());}
    static void insert(Connection c,JsonObject track)throws Exception{Store.update(c,"INSERT INTO tracks(id,timeline_id,version,status,data) VALUES(?,?,?,?,?)",Json.required(track,"id"),Json.required(track,"timelineId"),Json.number(track,"version",1),Json.required(track,"status"),track);save(c,track);}
    static void save(Connection c,JsonObject track)throws Exception{track.addProperty("updatedAt",Json.now());track.addProperty("sequence",Store.cursor(c));Store.update(c,"UPDATE tracks SET version=?,status=?,data=? WHERE id=?",Json.number(track,"version",1),Json.required(track,"status"),track,Json.required(track,"id"));Store.update(c,"INSERT INTO track_versions(id,track_id,version,data) VALUES(?,?,?,?)",Json.id(),Json.required(track,"id"),Json.number(track,"version",1),track);}
    static JsonObject require(Connection c,String trackId,long expected,boolean active)throws Exception{JsonObject track=Store.document(c,"tracks",trackId);expect(expected,Json.number(track,"version",0));if(active&&!Json.required(track,"status").equals("active"))throw error(409,"track_archived","该轨迹已删除或由结构操作替代，只能查看历史或处理待清理贡献。");return track;}
    static JsonObject timeline(Connection c,JsonObject track,long expected)throws Exception{JsonObject timeline=Store.document(c,"track_timelines",Json.required(track,"timelineId"));expect(expected,Json.number(timeline,"version",0));currentTemplate(c,timeline);return timeline;}
    static JsonObject affected(Connection c,JsonObject timeline,JsonObject before,JsonObject after)throws Exception{return TrackInterpolation.affectedIntervals(Json.object(timeline,"template"),helperTimeline(c,timeline),helper(before),helper(after));}
    static void dirty(Connection c,String trackId,Collection<String> frames)throws Exception{for(String frame:frames)Store.update(c,"INSERT OR IGNORE INTO track_dirty_frames(track_id,frame_id) VALUES(?,?)",trackId,frame);}
    static List<String> strings(JsonArray values){List<String> result=new ArrayList<>();for(JsonElement value:values)result.add(value.getAsString());return result;}
    static JsonObject mutation(Connection c,JsonObject track,JsonObject affected)throws Exception{return Json.obj("track",view(c,track),"affected",affected);}
    JsonObject create(JsonObject p){FlowPlans.keys(p,"timelineId","timelineVersion","classId","name");String timelineId=id(p,"timelineId"),classId=id(p,"classId"),title=name(p,"name","对象轨迹");long expected=version(p,"timelineVersion");return store.tx(c->{JsonObject timeline=Store.document(c,"track_timelines",timelineId);expect(expected,Json.number(timeline,"version",0));currentTemplate(c,timeline);boolean found=false;for(JsonElement value:Json.array(Json.object(timeline,"template"),"classes"))found|=classId.equals(Json.required(value.getAsJsonObject(),"id"));if(!found)throw error(422,"track_class_invalid","轨迹类别不在冻结模板中。");if(Json.number(Store.one(c,"SELECT COUNT(*) AS n FROM tracks WHERE timeline_id=? AND status='active'",timelineId),"n",0)>=1000)throw error(413,"track_limit","一个时间轴最多 1000 条活动轨迹。");JsonObject track=record(timeline,classId,title,null);TrackTimelines.event(c,"created",timeline,Json.required(track,"id"),null,new JsonObject());insert(c,track);return view(c,track);});}
    JsonObject list(JsonObject p){FlowPlans.keys(p,"timelineId","includeArchived","limit","offset");String timelineId=id(p,"timelineId");FlowPlans.bool(p,"includeArchived");int limit=pageInt(p,"limit",100,1,100),offset=pageInt(p,"offset",0,0,Integer.MAX_VALUE);return store.read(c->{Store.document(c,"track_timelines",timelineId);String where="timeline_id=?"+(Json.bool(p,"includeArchived",false)?"":" AND status='active'");JsonArray items=new JsonArray();for(JsonElement value:Store.docs(c,"SELECT data FROM tracks WHERE "+where+" ORDER BY rowid LIMIT ? OFFSET ?",timelineId,limit,offset))items.add(view(c,value.getAsJsonObject()));return Json.obj("items",items,"total",Store.one(c,"SELECT COUNT(*) AS n FROM tracks WHERE "+where,timelineId).get("n"));});}
    JsonObject get(JsonObject p){FlowPlans.keys(p,"trackId","version");String trackId=id(p,"trackId");return store.read(c->{JsonObject track=Store.document(c,"tracks",trackId);if(p.has("version")){JsonObject row=Store.one(c,"SELECT data FROM track_versions WHERE track_id=? AND version=?",trackId,version(p,"version"));if(row==null)throw error(404,"track_version_missing","轨迹历史版本不存在。");track=Json.parse(Json.required(row,"data"));}return view(c,track);});}
    JsonObject update(JsonObject p){FlowPlans.keys(p,"trackId","baseVersion","name");String trackId=id(p,"trackId"),title=name(p,"name",null);if(title==null)throw error(400,"track_name_required","请提供轨迹名称。");long expected=version(p,"baseVersion");return store.tx(c->{JsonObject before=require(c,trackId,expected,true),timeline=Store.document(c,"track_timelines",Json.required(before,"timelineId"));currentTemplate(c,timeline);JsonObject after=before.deepCopy();after.addProperty("name",title);after.addProperty("version",expected+1);JsonObject change=affected(c,timeline,before,after);TrackTimelines.event(c,"updated",timeline,trackId,null,Json.obj("name",title));save(c,after);return mutation(c,after,change);});}
    JsonObject keys(JsonObject p){FlowPlans.keys(p,"trackId","aroundFrameId","limit","offset");String trackId=id(p,"trackId");int limit=pageInt(p,"limit",100,1,500),offset=pageInt(p,"offset",0,0,Integer.MAX_VALUE);return store.read(c->{JsonObject track=Store.document(c,"tracks",trackId);List<JsonObject> frames=TrackTimelines.frames(c,Json.required(track,"timelineId"));Map<String,Integer> positions=new HashMap<>();Map<String,JsonObject> byId=new HashMap<>();for(int i=0;i<frames.size();i++){positions.put(Json.required(frames.get(i),"frameId"),i);byId.put(Json.required(frames.get(i),"frameId"),frames.get(i));}List<JsonObject> keys=new ArrayList<>();for(JsonElement value:Json.array(track,"keyframes"))keys.add(value.getAsJsonObject());keys.sort(Comparator.comparingInt(key->positions.get(Json.required(key,"frameId"))));JsonArray items=new JsonArray();for(int i=offset;i<keys.size()&&items.size()<limit;i++)items.add(keyView(keys.get(i),byId.get(Json.required(keys.get(i),"frameId"))));JsonObject result=Json.obj("items",items,"total",keys.size());if(p.has("aroundFrameId")){Integer anchor=positions.get(id(p,"aroundFrameId"));if(anchor==null)throw error(404,"track_frame_missing","定位帧不在时间轴中。");JsonObject previous=null,next=null;for(JsonObject key:keys){int position=positions.get(Json.required(key,"frameId"));if(position<anchor)previous=key;else if(position>anchor&&next==null)next=key;}result.add("previous",previous==null?JsonNull.INSTANCE:keyView(previous,byId.get(Json.required(previous,"frameId"))));result.add("next",next==null?JsonNull.INSTANCE:keyView(next,byId.get(Json.required(next,"frameId"))));}return result;});}
    JsonObject saveKey(JsonObject p){
        FlowPlans.keys(p,"trackId","baseVersion","timelineVersion","keyframeId","frameId","state","annotation","baseAnnotationVersion","baseDraftSavedAt");String trackId=id(p,"trackId"),frameId=id(p,"frameId"),state=id(p,"state");if(!Set.of("located","occluded","enter","exit","unlocatable").contains(state))throw error(400,"track_keyframe_state_invalid","关键帧状态无效。");long expected=version(p,"baseVersion"),timelineVersion=version(p,"timelineVersion"),annotationVersion=version(p,"baseAnnotationVersion");if(p.has("baseDraftSavedAt")&&!p.get("baseDraftSavedAt").isJsonNull())FlowPlans.string(p,"baseDraftSavedAt",100);
        JsonObject inspected=store.read(c->{JsonObject track=require(c,trackId,expected,true),timeline=timeline(c,track,timelineVersion);return frame(c,Json.required(timeline,"id"),frameId);});timelines.verifyFile(inspected);
        return store.tx(c->{JsonObject before=require(c,trackId,expected,true),timeline=timeline(c,before,timelineVersion),frame=frame(c,Json.required(timeline,"id"),frameId),asset=current(c,frame),live=state(c,frame);expect(annotationVersion,Json.number(live,"annotationVersion",-1));if(!Objects.equals(Json.str(p,"baseDraftSavedAt",null),Json.str(live,"draftSavedAt",null)))throw error(409,"track_draft_changed","该帧草稿已变化，请重新载入。");if(!frame.equals(inspected))throw error(409,"track_baseline_changed","关键帧基准或场景信息已变化。");
            JsonElement annotation=JsonNull.INSTANCE;if(state.equals("unlocatable")){if(p.has("annotation")&&!p.get("annotation").isJsonNull())throw error(400,"track_keyframe_state_invalid","不可定位关键帧不能包含几何。");}else{if(!p.has("annotation")||!p.get("annotation").isJsonObject())throw error(400,"track_annotation_required","可定位关键帧需要完整单对象标注。");JsonObject validated=Annotations.validate(Json.arr(p.get("annotation")),frame,Json.object(timeline,"template")).get(0).getAsJsonObject();if(!Json.required(validated,"classId").equals(Json.required(before,"classId")))throw error(409,"track_class_conflict","关键帧类别与轨迹类别不一致。");
                // 关键帧绑定已经保存的对象，避免只存在轨迹表的端点漏出正式数据集。
                if(!live.get("draftSavedAt").isJsonNull())throw error(409,"track_keyframe_annotation_unsaved","请先保存或放弃该帧草稿，再设置关键帧。");boolean saved=false;for(JsonElement value:Json.array(asset,"annotations"))saved|=value.equals(validated);if(!saved)throw error(409,"track_keyframe_annotation_unsaved","请先在标注工作台保存完整单图标注，再绑定其中的对象为关键帧。");annotation=validated;
            }
            JsonObject after=before.deepCopy();JsonArray keys=Json.array(after,"keyframes");String keyId=p.has("keyframeId")?id(p,"keyframeId"):Json.id();int replace=-1;for(int i=0;i<keys.size();i++){JsonObject key=keys.get(i).getAsJsonObject();if(Json.required(key,"keyframeId").equals(keyId))replace=i;else if(Json.required(key,"frameId").equals(frameId))throw error(409,"track_keyframe_duplicate","该轨迹在此帧已有关键帧，请明确更新原关键帧。");}if(p.has("keyframeId")&&replace<0)throw error(404,"track_keyframe_missing","要更新的关键帧不存在。");JsonObject key=Json.obj("keyframeId",keyId,"frameId",frameId,"objectId",after.get("objectId"),"state",state,"annotation",annotation,"sourceAnnotationVersion",annotationVersion,"sourceDraftSavedAt",live.get("draftSavedAt"));if(replace>=0)keys.set(replace,key);else keys.add(key);after.addProperty("version",expected+1);JsonObject change=affected(c,timeline,before,after);dirty(c,trackId,strings(Json.array(change,"affectedFrameIds")));TrackTimelines.event(c,"keyframe.saved",timeline,trackId,null,Json.obj("keyframeId",keyId,"frameId",frameId,"affectedFrameCount",Json.array(change,"affectedFrameIds").size()));save(c,after);return mutation(c,after,change);
        });
    }
    JsonObject deleteKey(JsonObject p){FlowPlans.keys(p,"trackId","baseVersion","timelineVersion","keyframeId");String trackId=id(p,"trackId"),keyId=id(p,"keyframeId");long expected=version(p,"baseVersion"),timelineVersion=version(p,"timelineVersion");return store.tx(c->{JsonObject before=require(c,trackId,expected,true),timeline=timeline(c,before,timelineVersion),after=before.deepCopy();JsonArray keys=Json.array(after,"keyframes");boolean removed=false;for(int i=keys.size()-1;i>=0;i--)if(Json.required(keys.get(i).getAsJsonObject(),"keyframeId").equals(keyId)){keys.remove(i);removed=true;}if(!removed)throw error(404,"track_keyframe_missing","关键帧不存在。");after.addProperty("version",expected+1);JsonObject change=affected(c,timeline,before,after);dirty(c,trackId,strings(Json.array(change,"affectedFrameIds")));TrackTimelines.event(c,"keyframe.deleted",timeline,trackId,null,Json.obj("keyframeId",keyId));save(c,after);return mutation(c,after,change);});}
    static JsonObject normalizedAffected(JsonObject plan){JsonObject result=plan.deepCopy();for(String key:List.of("changedKeyframes","affectedIntervals","affectedFrameIds","mutableCandidateFrameIds","eligibleCandidateFrameIds","protectedFrames","applyPreconditions"))if(!result.has(key))result.add(key,new JsonArray());result.addProperty("candidateOnly",true);result.addProperty("humanConfirmed",false);result.addProperty("requiresRecompute",!Json.array(result,"affectedFrameIds").isEmpty());result.remove("planHash");result.addProperty("planHash",hash(result));return result;}
    static Set<String> headFrames(Connection c,String timelineId,List<String> trackIds)throws Exception{Set<String> ids=new LinkedHashSet<>();for(String trackId:trackIds)for(JsonObject row:Store.rows(c,"SELECT f.frame_id FROM track_contribution_heads h JOIN timeline_frames f ON f.asset_id=h.asset_id WHERE h.track_id=? AND f.timeline_id=?",trackId,timelineId))ids.add(Json.required(row,"frame_id"));return ids;}
    JsonObject delete(JsonObject p){FlowPlans.keys(p,"trackId","baseVersion","timelineVersion");String trackId=id(p,"trackId");long expected=version(p,"baseVersion"),timelineVersion=version(p,"timelineVersion");return store.tx(c->{JsonObject before=require(c,trackId,expected,true),timeline=timeline(c,before,timelineVersion),after=before.deepCopy(),empty=after.deepCopy();empty.add("keyframes",new JsonArray());JsonObject change=affected(c,timeline,before,empty);Set<String> scope=new LinkedHashSet<>(strings(Json.array(change,"affectedFrameIds")));scope.addAll(headFrames(c,Json.required(timeline,"id"),List.of(trackId)));change.add("affectedFrameIds",Json.element(scope));after.addProperty("status","deleted");after.addProperty("version",expected+1);dirty(c,trackId,scope);TrackTimelines.event(c,"deleted",timeline,trackId,null,new JsonObject());save(c,after);JsonObject result=mutation(c,after,normalizedAffected(change));if(!scope.isEmpty())result.add("generation",generations.structural(c,timeline,after,List.of(),List.of(after),scope));return result;});}
    private static JsonArray enrichedKeys(JsonArray planned,List<JsonObject> sources){Map<String,JsonObject> originals=new HashMap<>();for(JsonObject source:sources)for(JsonElement value:Json.array(source,"keyframes"))originals.put(Json.required(value.getAsJsonObject(),"keyframeId"),value.getAsJsonObject());JsonArray result=new JsonArray();for(JsonElement value:planned){JsonObject key=value.getAsJsonObject().deepCopy(),original=originals.get(Json.required(key,"keyframeId"));if(original!=null)for(String field:List.of("sourceAnnotationVersion","sourceDraftSavedAt"))if(original.has(field))key.add(field,original.get(field));result.add(key);}return result;}
    JsonObject split(JsonObject p){FlowPlans.keys(p,"trackId","baseVersion","timelineVersion","splitFrameId","leftName","rightName");String trackId=id(p,"trackId"),boundary=id(p,"splitFrameId");long expected=version(p,"baseVersion"),timelineVersion=version(p,"timelineVersion");return store.tx(c->{JsonObject before=require(c,trackId,expected,true),timeline=timeline(c,before,timelineVersion);JsonObject left=record(timeline,Json.required(before,"classId"),name(p,"leftName",Json.required(before,"name")+" · 前段"),Json.required(before,"objectId")),right=record(timeline,Json.required(before,"classId"),name(p,"rightName",Json.required(before,"name")+" · 后段"),Json.required(before,"objectId"));JsonObject plan=TrackInterpolation.splitPlan(Json.object(timeline,"template"),helperTimeline(c,timeline),helper(before),boundary,Json.required(left,"id"),Json.required(right,"id"));left.add("keyframes",enrichedKeys(Json.array(Json.object(plan,"leftTrack"),"keyframes"),List.of(before)));right.add("keyframes",enrichedKeys(Json.array(Json.object(plan,"rightTrack"),"keyframes"),List.of(before)));left.add("derivedFrom",Json.arr(trackId));right.add("derivedFrom",Json.arr(trackId));JsonObject archived=before.deepCopy();archived.addProperty("status","superseded");archived.addProperty("version",expected+1);archived.add("replacedBy",Json.arr(left.get("id"),right.get("id")));Set<String> scope=new LinkedHashSet<>(strings(Json.array(plan,"affectedFrameIds")));scope.addAll(headFrames(c,Json.required(timeline,"id"),List.of(trackId)));scope.addAll(TrackGenerations.outputScope(c,timeline,List.of(left,right)));TrackTimelines.event(c,"split",timeline,trackId,null,Json.obj("leftTrackId",left.get("id"),"rightTrackId",right.get("id"),"splitFrameId",boundary));save(c,archived);insert(c,left);insert(c,right);for(JsonObject track:List.of(archived,left,right))dirty(c,Json.required(track,"id"),scope);JsonObject change=normalizedAffected(plan);JsonObject bridge=Json.object(plan,"removedInterval").deepCopy();bridge.addProperty("phase","before");change.add("affectedIntervals",Json.arr(bridge));change.add("affectedFrameIds",Json.element(scope));JsonObject generation=generations.structural(c,timeline,archived,List.of(left,right),List.of(archived),scope);return Json.obj("sourceTrack",view(c,archived),"leftTrack",view(c,left),"rightTrack",view(c,right),"affected",normalizedAffected(change),"generation",generation);});}
    JsonObject merge(JsonObject p){FlowPlans.keys(p,"leftTrackId","leftVersion","rightTrackId","rightVersion","timelineVersion","name","confirmSameObject");FlowPlans.bool(p,"confirmSameObject");String leftId=id(p,"leftTrackId"),rightId=id(p,"rightTrackId");if(leftId.equals(rightId))throw error(400,"track_merge_invalid","不能合并同一轨迹。");long leftVersion=version(p,"leftVersion"),rightVersion=version(p,"rightVersion"),timelineVersion=version(p,"timelineVersion");return store.tx(c->{JsonObject left=require(c,leftId,leftVersion,true),right=require(c,rightId,rightVersion,true),timeline=timeline(c,left,timelineVersion);if(!Json.required(right,"timelineId").equals(Json.required(timeline,"id"))||!Json.required(left,"classId").equals(Json.required(right,"classId")))throw error(409,"track_identity_conflict","只能合并同一时间轴、同一类别的轨迹。");boolean different=!Json.required(left,"objectId").equals(Json.required(right,"objectId"));if(different&&!Json.bool(p,"confirmSameObject",false))throw error(409,"track_identity_conflict","对象身份不同，请明确确认它们是同一对象后合并。");JsonObject rightResolved=right.deepCopy();rightResolved.add("objectId",left.get("objectId"));for(JsonElement key:Json.array(rightResolved,"keyframes"))key.getAsJsonObject().add("objectId",left.get("objectId"));JsonObject merged=record(timeline,Json.required(left,"classId"),name(p,"name",Json.required(left,"name")+" · 合并"),Json.required(left,"objectId"));JsonObject plan=TrackInterpolation.mergePlan(Json.object(timeline,"template"),helperTimeline(c,timeline),helper(left),helper(rightResolved),Json.required(merged,"id"));merged.add("keyframes",enrichedKeys(Json.array(Json.object(plan,"track"),"keyframes"),List.of(left,right)));merged.add("derivedFrom",Json.arr(leftId,rightId));merged.add("identityResolution",Json.obj("explicitSameObject",different,"sourceObjectIds",Json.arr(left.get("objectId"),right.get("objectId")),"resolvedObjectId",merged.get("objectId")));Set<String> scope=new LinkedHashSet<>(strings(Json.array(plan,"affectedFrameIds")));scope.addAll(headFrames(c,Json.required(timeline,"id"),List.of(leftId,rightId)));scope.addAll(TrackGenerations.outputScope(c,timeline,List.of(merged)));TrackTimelines.event(c,"merged",timeline,Json.required(merged,"id"),null,Json.obj("sourceTrackIds",Json.arr(leftId,rightId),"explicitIdentityResolution",different));for(JsonObject source:List.of(left,right)){source.addProperty("status","superseded");source.addProperty("version",Json.number(source,"version",1)+1);source.add("replacedBy",Json.arr(merged.get("id")));save(c,source);dirty(c,Json.required(source,"id"),scope);}insert(c,merged);dirty(c,Json.required(merged,"id"),scope);JsonObject change=normalizedAffected(plan),bridge=Json.object(plan,"addedInterval").deepCopy();bridge.addProperty("phase","after");change.add("affectedIntervals",Json.arr(bridge));change.add("affectedFrameIds",Json.element(scope));JsonObject generation=generations.structural(c,timeline,merged,List.of(merged),List.of(left,right),scope);return Json.obj("sourceTracks",Json.arr(view(c,left),view(c,right)),"track",view(c,merged),"affected",normalizedAffected(change),"generation",generation);});}
}
